// Generated from the authoritative 2.2.1 Markdown. Run npm run rules.
export const MISSION_CARDS: Record<string,{code:string;title:string;body:string}> = {"A1":{"code":"A1","title":"A1. Cut the Shield / K1. Break the Seal","body":"**Поле:** THREE, три interaction-узла Shield Nodes / Stasis Seals. **Атакующий:** BREACH / BREAK действующий узел, обычный Action; отключить навсегда, 10 VP. Все три отключены -> ещё 10 VP. **Defender:** в конце боя по 10 VP за каждый действующий узел. Отдельных VP за Warlord нет. Узлы не objectives.\n\nПосле первого отключения в каждом раунде все формации в 6 от этого узла проходят Battle-shock. После второго отключённого узла за весь бой атакующий получает 1 CP по core limits. Больше VP - победа; миссия не заканчивается досрочно после третьего узла."},"K1":{"code":"K1","title":"A1. Cut the Shield / K1. Break the Seal","body":"**Поле:** THREE, три interaction-узла Shield Nodes / Stasis Seals. **Атакующий:** BREACH / BREAK действующий узел, обычный Action; отключить навсегда, 10 VP. Все три отключены -> ещё 10 VP. **Defender:** в конце боя по 10 VP за каждый действующий узел. Отдельных VP за Warlord нет. Узлы не objectives.\n\nПосле первого отключения в каждом раунде все формации в 6 от этого узла проходят Battle-shock. После второго отключённого узла за весь бой атакующий получает 1 CP по core limits. Больше VP - победа; миссия не заканчивается досрочно после третьего узла."},"A2":{"code":"A2","title":"A2. The Long Vigil / K2. Command Crypt","body":"**Поле:** центральный objective Vault / Command Dais; два interaction-узла Relay / Control Spire в (0.25L,0.5W) и (0.75L,0.5W). Pool Capacity +10 п.п.: 85% обычно, 70% при временном внешнем проломе. **Счёт:** в конце каждого раунда 5 VP за физический контроль центра.\n\nОбе стороны могут HACK / CONTROL каждый боковой узел один раз: 5 VP и 1 Intel после боя. Метка успешного взлома не заменяет физический контроль. После первого взлома атакующего Defender получает 1 CP; после второго атакующий выбирает один дополнительный Tactical Asset: Smoke Screen, Field Reserves или Hard Evacuation. Без дублей; Field Reserves недоступен, если начало R2 уже прошло. После первого за раунд перехода центра от одного контролирующего игрока к другому все формации в 6 центра проходят Battle-shock. Первое занятие нейтрального центра не считается таким переходом. Победителя определяют VP."},"K2":{"code":"K2","title":"A2. The Long Vigil / K2. Command Crypt","body":"**Поле:** центральный objective Vault / Command Dais; два interaction-узла Relay / Control Spire в (0.25L,0.5W) и (0.75L,0.5W). Pool Capacity +10 п.п.: 85% обычно, 70% при временном внешнем проломе. **Счёт:** в конце каждого раунда 5 VP за физический контроль центра.\n\nОбе стороны могут HACK / CONTROL каждый боковой узел один раз: 5 VP и 1 Intel после боя. Метка успешного взлома не заменяет физический контроль. После первого взлома атакующего Defender получает 1 CP; после второго атакующий выбирает один дополнительный Tactical Asset: Smoke Screen, Field Reserves или Hard Evacuation. Без дублей; Field Reserves недоступен, если начало R2 уже прошло. После первого за раунд перехода центра от одного контролирующего игрока к другому все формации в 6 центра проходят Battle-shock. Первое занятие нейтрального центра не считается таким переходом. Победителя определяют VP."},"A3":{"code":"A3","title":"A3. Sever the Vigil / K3. The Nameless Throne","body":"**Поле:** FINAL. Четыре interaction-узла Consoles / Chronal Anchors и Throne. Атакующий DISABLE / DESTROY действующий узел: отключить, 5 VP. После каждого отключения Defender выбирает свою формацию в 6 Throne: +2 total OC до конца раунда, максимум +1/model, не складывается с собой. После четвёртого отключения Defensive Asset Defender больше не действует, включая предоставленные им barricades; уже причинённые ранения не отменяются.\n\nПосле двух отключённых узлов Throne становится objective и с R3 доступен **CLAIM, CORE Action**: физический контроль Throne при старте и completion, без Shoot/Charge/Action + Advance. Успех один раз даёт 20 VP и постоянную запись CLAIM. Потеря контроля не стирает запись. Defender в конце получает 5 VP за действующий узел и 20, если CLAIM не выполнен.\n\n**Обязательная победа:** атакующий выигрывает только при completed CLAIM и физическом контроле Throne в конце R5 после hazards. Иначе выигрывает Defender, независимо от VP. Раннего окончания нет; дополнительные Action VP и кризис не обходят gate."},"K3":{"code":"K3","title":"A3. Sever the Vigil / K3. The Nameless Throne","body":"**Поле:** FINAL. Четыре interaction-узла Consoles / Chronal Anchors и Throne. Атакующий DISABLE / DESTROY действующий узел: отключить, 5 VP. После каждого отключения Defender выбирает свою формацию в 6 Throne: +2 total OC до конца раунда, максимум +1/model, не складывается с собой. После четвёртого отключения Defensive Asset Defender больше не действует, включая предоставленные им barricades; уже причинённые ранения не отменяются.\n\nПосле двух отключённых узлов Throne становится objective и с R3 доступен **CLAIM, CORE Action**: физический контроль Throne при старте и completion, без Shoot/Charge/Action + Advance. Успех один раз даёт 20 VP и постоянную запись CLAIM. Потеря контроля не стирает запись. Defender в конце получает 5 VP за действующий узел и 20, если CLAIM не выполнен.\n\n**Обязательная победа:** атакующий выигрывает только при completed CLAIM и физическом контроле Throne в конце R5 после hazards. Иначе выигрывает Defender, независимо от VP. Раннего окончания нет; дополнительные Action VP и кризис не обходят gate."},"B1":{"code":"B1","title":"B1. Reliquary Hunt","body":"**FIVE, переносимые реликварии, не objectives.** PICK UP, носитель -1 Move. DELIVER в свою зону: 8 VP, центральный 13. В конце боя предмет у живого носителя: 5 VP, центральный 10; с доставкой не складывается. Доставленный удаляется.\n\nПервый PICK UP центрального предмета за бой: D6 1-2 формация носителя Battle-shocked; 3-6 сторона получает 1 Intel после боя. Повторного броска при смене носителя нет. Победитель даёт +1 XP одному своему ID, успешно выполнившему PICK UP, сверх обычного Deed."},"B2":{"code":"B2","title":"B2. Bone Choir","body":"**CROSS objectives.** Command-scoring R2-R5: 3 VP за хотя бы один свой objective; ещё 3, если своих больше, чем у противника; ещё 2 за центр. Максимум 8 за шаг.\n\nНачало каждого раунда D6: 1-2 все формации в 6 центра проходят Battle-shock; 3-4 ничего; 5-6 формации в range центра получают +2 total OC до конца раунда. Провал такого теста на натуральной сумме 2: Choir +1 после боя, максимум один общий прирост за миссию."},"B3":{"code":"B3","title":"B3. Procession of the Dead","body":"**Движущийся interaction-объект**, начало (0,W/2), выход (L,W/2); длинные зоны deployment. В конце раунда процессия движется по x на 9/9/12 для полей 44×30 / 44×44 / 60×44. Затем больший Area OC в 6 от новой позиции даёт стороне 7 VP, равенство 0. При первом достижении выхода тому же победителю OC ещё 15 VP, один раз. Объект остаётся на выходе без повторного бонуса.\n\nФормация хотя бы одной моделью в 3 получает Cover и -1 Advance distance, пока находится там. Объект не перевозит модели. Победителю +15 Supply."},"C1":{"code":"C1","title":"C1. Falling Sky","body":"**CROSS objectives**, индексы: центр 1, левый/правый средние 2/3, тыл атакующего/защитника 4/5. Command-scoring R2-R5: 5 VP, если контролируете больше objectives; ещё 3 за центр.\n\nНачало раунда: два D5 (D6 с повтором 6). Если первые два равны, формации в 4 этого objective один раз на 4+ получают D3 mortal wounds; затем второй индекс перебрасывается до другого. Два конечных разных objectives дают Rough Ground radius 4 до конца раунда. VEHICLE получает -1 Casualty только при гибели от этого взрыва обломков, не за любую гибель в области."},"C2":{"code":"C2","title":"C2. Counterweight","body":"**Platform**, interaction-объект в центре, выходы y=0/W. В конце раунда один раз сравнить Area OC в 3 Platform. Большая сторона получает 5 VP и двигает её ровно на 6 к своей edge, остановившись на краю, если он ближе. При равенстве нет движения/VP. Первое касание своей edge даёт ещё 20 VP, Platform удаляется. Контроль проверяется **до** движения; повторной проверки после него нет.\n\nПока Platform существует, формации в 3 получают Cover против ranged атак моделей дальше 18 от атакуемой модели. Platform не перевозит войска. Победителю +20 Supply. Двойного scoring обеим сторонам за один раунд нет."},"C3":{"code":"C3","title":"C3. Zero-G Breach","body":"**SHORT FOUR objectives**, short-edge deployment; полоса x от L/2-4 до L/2+4. Конец раунда: 4 VP за свой objective, максимум 12; ещё 2 за enemy persistent ID, чью последнюю модель ваша сторона уничтожила в полосе в этом раунде, максимум 4.\n\nINFANTRY/JUMP PACK +1 Move и +1 Advance distance. При натуральной сумме Charge >8 разрешённая дистанция -1 до выбора legal charge move. Победителю Airlift Window до конца следующей своей Activation: первая атака через Orbital Lift без базовой цены Intel, но надбавки и условия Origin/Home сохраняются."},"D1":{"code":"D1","title":"D1. Vat Breach","body":"**THREE Vats**, interaction-объекты. Атакующий OVERLOAD действующий Vat: отключить, 10 VP; все три -> ещё 10. Defender в конце получает 10 за каждый целый Vat.\n\nОтключённый Vat оставляет Toxic area radius 5. В конце собственного хода каждая формация хотя бы частью в одной или нескольких таких областях на 4+ получает D3 mortal wounds, максимум одна проверка за ход. Погибший именно от этого hazard ID получает -1 Casualty. VP определяют победителя."},"D2":{"code":"D2","title":"D2. Harvest Line","body":"**FOUR переносимых Caskets.** PICK UP; DELIVER моделью носителя wholly в 3 своей edge: 10 VP; удержание у живого носителя в конце: 5. DESTROY лежащий Casket: 5 VP и удалить. Переносимый чужой предмет не является допустимой целью DESTROY.\n\nПервый PICK UP или DESTROY каждого Casket: D6 1 формация исполнителя Battle-shocked, 2-5 ничего, 6 стороне 10 Supply. Повторного открытия нет. Победитель выбирает 25 Supply либо бесплатное снятие 1 Damage своему участвовавшему ID."},"D3":{"code":"D3","title":"D3. Red Conveyor","body":"**Три полосы width 4** с центрами x=0.25L/0.5L/0.75L, от y=d до W-d; objective в центре каждой. Начало раунда: второй игрок, затем первый могут переместить каждую свою eligible формацию с моделью на полосе до 3 вдоль +y или -y как Normal Move. Один move на формацию, даже на пересечении областей. Engaged не двигается и не получает штраф; обычная законность/coherency сохраняются. Если legal move есть, добровольный отказ: D6 1 ->1 mortal wound.\n\nКонец раунда: центр 5 VP, каждый боковой objective 3. Глобальное событие aftermath: три D66 вместо обычных двух D; победитель выбирает один, при Draw Defender. Один платный reroll заменяет выбранный результат одним новым D66."},"E1":{"code":"E1","title":"E1. Armoured Train","body":"**Поезд** движется как B3, но Area OC radius 3; конец раунда после движения больший OC даёт 6 VP, первое достижение выхода ещё 10. **BOARD** в 3 поезда: 4 VP один раз на исходную формацию, максимум 12 на сторону. Разделение Attached Unit не создаёт новые BOARD-награды; действие не сажает модели на поезд.\n\nПри первом за раунд пересечении пути y=W/2 каждой формацией бросить D6: 1 разрешённая дистанция move -2. Бросок до пересечения; можно закончить перед линией, нельзя нарушить законность Charge. Один такой бросок за формацию за раунд. Поезд не terrain/transport. Победителю +25 Supply."},"E2":{"code":"E2","title":"E2. Break the Rails","body":"**FIVE Junctions**, interaction-объекты. Атакующий DEMOLISH целый Junction: отключить, 8 VP. Defender в конце 8 за каждый целый. Отключение оставляет Rough Ground radius 3; отдельного objective scoring нет.\n\nЕсли к началу R5 уничтожены минимум три Junction, действует Ash Storm до конца боя: ranged атаки нельзя назначать по целям дальше 24 от атакующей модели, по обычной core target legality. При победе атакующего E после захвата получает Exhausted 2."},"E3":{"code":"E3","title":"E3. Black Freight","body":"**SIX Cargo**, interaction-объекты. SEARCH удаляет Cargo: D6 1 -> D3 mortal wounds bearer; 2-4 ->5 VP; 5 ->8 VP; 6 ->8 VP и 10 Supply. Completed reward не отменяется немедленной гибелью actor.\n\nПосле третьего SEARCH суммарно обеих сторон оставшиеся Cargo volatile. Любая сторона может DESTROY CARGO такого объекта: удалить без награды; каждая формация в 3 на 4+ получает D3 mortal wounds. Ничейные объекты не имеют вражеского владельца. Заработанный Supply сохраняется независимо от исхода."},"F1":{"code":"F1","title":"F1. Kill the Signal","body":"**THREE Relay objectives.** Command-scoring R2-R5: 3 VP за контролируемый Relay, максимум 9. HACK neutral/enemy-tag Relay: первый completion стороны на нём 5 VP, поставить own tag. Повторный перехват меняет tag без новых VP; own-tag HACK недоступен.\n\nСвои формации в 3 own-tag Relay имеют +2 total OC; несколько Relay не суммируются. Физический контроль по-прежнему определяется OC, а не tag. Победителю +1 Intel."},"F2":{"code":"F2","title":"F2. Ghost Frequency","body":"**FIVE Signals**, скрытые interaction-объекты 1-5. Система равномерно и тайно выбирает один настоящий при создании боя. SCAN ещё не раскрытого Signal делает его публичным: первый reveal ложного 3 VP, настоящего 10 VP только обнаружившей стороне. После раскрытия настоящего остальные считаются ложными без выдачи discovery VP. Повторных SCAN нет; никакие модификаторы не меняют скрытый выбор.\n\nНастоящий Signal становится objective: физический контроль в конце каждого раунда 5 VP. При его открытии actor тестирует Battle-shock; провал -> Choir +1 после боя. Победитель получает базовый Recon Lock бесплатно на следующую настольную битву своей стороны; token истекает после её Muster, не после небоевой Activation. Доплата Noosphere Static сохраняется."},"F3":{"code":"F3","title":"F3. Last Transmission","body":"**THREE**, центральный Array и боковые Power Nodes, все interaction-объекты. Атакующий HACK каждый Power Node один раз за 5 VP. Хотя бы один взлом открывает UPLOAD у Array: 25 VP, максимум один успех.\n\nDefender получает 5 VP в конце каждого раунда, к которому UPLOAD ещё не завершён, и ещё 15 в конце боя, если его не было. Первый провал начатого UPLOAD за бой вызывает Battle-shock всем формациям в 6 Array. Общие completion requirements обязательны; Field Engineers может добавить контроль, но не переносит completion на новый ход. При захвате F получает Relay Disruption до конца следующей Activation нового владельца."},"G1":{"code":"G1","title":"G1. Pilgrimage into Glass","body":"**CROSS objectives**, центр Altar. Конец раунда: четыре внешних по 2 VP, центр 6. С R3 **COMMUNE**: обычный старт, но completion в конце раунда при сохранённых общих условиях и физическом контроле Altar. Если обе стороны ожидают completion, больший Area OC даёт одного исполнителя; при равенстве оба провалены. Всего один успешный COMMUNE за бой: 8 VP и Choir +1.\n\nНачало раунда D6: 1-2 формации в 6 Altar получают -1 к Battle-shock tests; 3-4 ничего; 5-6 эти формации +2 total OC. Длительность до конца раунда. Победитель выбирает случайный Relic либо 1 Intel."},"G2":{"code":"G2","title":"G2. Beneath the Altar","body":"**TRIANGLE Descent Nodes**, interaction-объекты. CONTROL neutral/enemy-tag Node ставит own tag; первый completion стороны на каждом Node 6 VP. Перехват без повторной награды; own-tag недоступен. Конец раунда: минимум два своих tag дают 6 VP; первый конец раунда со всеми тремя ещё 10, один раз.\n\nПервый completed Action раунда вызывает Shear: противник выбирает формацию действовавшей стороны в 3 этого Node; на 4+ ей D3 mortal wounds. Нет такой формации - эффект пропадает. Tag сохраняется без непрерывного OC. После боя Choir +1."},"G3":{"code":"G3","title":"G3. The Black Choir","body":"**CROSS objectives**, центр Altar. Конец раунда 3 VP за свой objective, максимум 9. LISTEN у Altar: 5 VP, максимум два успешных выполнения на сторону за бой, не более одного за раунд.\n\nPulse в начале раунда: R1 все -1 Advance distance до конца раунда; R2 первый failed save каждой стороны в этом раунде можно перебросить; R3 все формации в 9 Altar проходят Battle-shock; R4 в 9 нет Cover; R5 в 9 формации +2 total OC. После боя Choir +2; обычный прирост за повторный бой в G также действует, общий cap 8."},"H1":{"code":"H1","title":"H1. Mirror March","body":"**CROSS objectives.** После deployment одновременно тайно выбрать по одной своей INFANTRY формации Decoy, раскрыть при срабатывании. Command-scoring R2-R5: 5 VP за минимум два своих objectives; ещё 5, если своих больше, чем у противника.\n\nПервый раз Decoy выбран целью ranged атаки модели дальше 12: после завершения **всех** атак этого enemy unit Decoy может выполнить legal Normal Move до 3, вне Engagement. Не отменяет атаки перемещением до их разрешения. Один use за бой. Победителю +1 Intel."},"H2":{"code":"H2","title":"H2. Buried in Glass","body":"**FIVE Fractures**, interaction-объекты. SHATTER удаляет объект: D6 1 ->0 VP и D3 mortal wounds bearer; 2-3 ->5 VP; 4-5 ->7 VP; 6 ->10 VP и 10 Supply. Максимум один начатый SHATTER на сторону за раунд. Центральный доступен только с R3, остальные с начала боя.\n\nПосле удаления Rough Ground radius 3. Две натуральные 6 на SHATTER одной стороны за бой -> Choir +1 после боя, максимум один общий прирост миссии. VP/награда завершённого Action не отменяется его hazard."},"H3":{"code":"H3","title":"H3. Heat Death","body":"**Safe Zone** - часть поля внутри круга radius 18 от центра; центр interaction-объект. Конец раунда: больший Area OC в 6 центра даёт 5 VP. За уничтоженный в этом раунде enemy persistent ID вне Safe Zone 2 VP, максимум 4; положение определяется по последней модели. В R5 по 10 VP за своего Warlord wholly внутри зоны.\n\nПосле scoring уменьшить radius на 3. Каждая формация wholly вне новой зоны: D6 1-2 ->D3 mortal wounds, для VEHICLE/MONSTER только 1. Если этот hazard уничтожил ID, противнику тоже начислить предусмотренные 2 VP в пределах cap текущего раунда до определения победителя. Основной scoring не повторять. Других наград нет."},"I1":{"code":"I1","title":"I1. Awakening Pits","body":"**FIVE:** четыре внешних interaction Nodes и центральный objective. CONTROL neutral/enemy-tag Node: 5 VP за первый completion стороны на нём, own tag. Перехват без новых 5; own-tag недоступен. Конец раунда 2 VP за каждый свой tag и 4 за физический контроль центра.\n\nПри первом общем захвате каждого Node D6: 1 actor Battle-shocked; 6 bearer +1 XP после боя; других эффектов нет. Победившие Necrons бесплатно снимают 1 Damage участвовавшему CANOPTEK/INFANTRY ID; победившие Deathwatch получают 1 Intel."},"I2":{"code":"I2","title":"I2. Tomb Street","body":"**Три lanes** по x: [0,L/3), [L/3,2L/3), [2L/3,L], на всю длину y; objective в центре каждой. Конец раунда по 5 VP за lane, если контролируете его objective и имеете свою модель wholly в enemy half за y=W/2 того же lane; максимум 15. Разные модели одной формации могут выполнить presence разных lanes.\n\nПервая уничтоженная формация каждого lane оставляет у последней модели Rubble radius 3: non-Obscuring, Rough Ground, Cover для моделей внутри. Не создаёт абстрактный Cover за спиной. Lane последней модели определяет единственное место rubble. Победителю +15 Supply."},"I3":{"code":"I3","title":"I3. Name of the Dead","body":"**THREE Obelisk objectives.** SCAN каждого каждой стороной один раз: 8 VP; все три ->ещё 10. В конце R3-R5 физический контроль центра даёт 2 VP. После каждого SCAN D6: 1-2 actor -1 к Battle-shock tests до конца боя; 6 стороне 1 Intel после боя. Одноимённый штраф не складывается на одной формации.\n\nКаждый, кто SCAN все три, получает 1 Fragment до cap 3; если это сделал хотя бы один игрок, общий Choir +1 после боя. Исследовать могут оба; за центр всё же стоит сражаться."},"J1":{"code":"J1","title":"J1. Assembly Line","body":"**FOUR Fabricator objectives.** Command-scoring R2-R5: 3 VP за свой действующий Fabricator, максимум 9. SHUTDOWN действующий Fabricator: 5 VP и навсегда отключить для обеих сторон. Больше он не даёт контроль/Actions/VP.\n\nПервый успешный SHUTDOWN раунда: D6 1 ->каждая формация в 3 получает D3 mortal wounds. Победитель выбирает 20 Supply или Recovery Cache."},"J2":{"code":"J2","title":"J2. Machine Hunger","body":"**FOUR Scrap**, переносимые предметы; Mouth - interaction точка центра. Лежащие Scrap в конце раунда движутся на 4 прямо к Mouth; достигнув 1 от него, исчезают без награды. Переносимые отдельно не двигаются.\n\nPICK UP в **1**, носитель -1 Move. DELIVER у своей edge за 8 VP либо FEED в 3 Mouth за 5 VP и 5 Supply. Оба обычные Actions, удаляют предмет при completion; один предмет не даёт обе награды. Supply от FEED сохраняется независимо от победы."},"J3":{"code":"J3","title":"J3. Kill Switch","body":"**THREE Safety Nodes**, interaction-объекты; центральный Node сдвинут на (0.5L,0.5W-g/4), Reactor точно в центре. OVERRIDE каждого Node: 6 VP за первый completion стороны на нём, постоянная личная запись, tag не нужен. После двух разных своих overrides ARM Reactor: 12 VP первый раз, состояние Armed своей стороны. DISARM Armed Reactor: 8 VP первый раз, состояние Unarmed. Повторные ARM/DISARM меняют только состояние. Нельзя ARM уже свой Armed или DISARM Unarmed.\n\nКонец R5: завершить Actions; если Armed, последнему ARM owner +10 VP, затем взрыв уничтожает **все** формации в 9 Reactor, Casualty -1. После этого итог VP. Взрыв не даёт HUNT или дополнительных kill VP. J получает Exhausted 2 и Sabotaged после боя независимо от победителя. Withdrawal не сбрасывает Armed: в досрочном исходе взрыв не происходит, состояния сектора всё равно накладываются."}}
export const CRISIS_CARDS:Record<string,string> = {"WAR":"Обе Main Forces до AL Effective; обычный sealed Muster и Field Underdog, без Pool. Поле 60×44, зоны y≤12 и y≥32. Engine - interaction точка (30,22). Три Conduit objectives: **(18,22), (42,22), (30,22)**; центральный objective и Engine имеют общий footprint, разные interactions. Геометрия симметрична относительно обеих сторон. Первый ход обычным roll-off.\n\n## Задачи\n\n**SEAL CONDUIT:** обычный Action при физическом контроле neutral/enemy-tag Conduit. Completion ставит own tag и личный Seal record этого объекта. Возврат enemy tag разрешён, но нового record не даёт; own-tag недоступен. Record - история, он не пропадает при потере tag.\n\n**OVERRIDE ENGINE:** CORE Action с R4 у Engine. При старте и completion требуется минимум два своих current Conduit tags и физический контроль Engine. Формация не Shoot/Charge, без Action + Advance/Shoot исключений. Успех даёт стороне постоянный **Override record**, максимум один. Противник тоже может получить свой record; это не мгновенная отмена первого.\n\n**Счёт:** в конце R2-R5 по 3 VP за каждый Conduit, где есть свой tag **и физический контроль**, максимум 9 за раунд. В конце R4/R5 ещё 6 VP за физический контроль Engine, если уже есть свой Override record. Максимум миссии 48 VP. Очки действуют для исхода, а не просто для декоративного лога.\n\n## Сопротивление машины\n\nВ начале R2-R5 случайный Conduit D3: каждая формация в 4 на 4+ получает D3 mortal wounds. В конце R5 после обычного scoring Final Pulse: каждой формации в 3 Engine 1 mortal wound. Затем определить кандидатов на победу.\n\n**Кандидат:** свой Override record, Seal records минимум двух разных Conduits и хотя бы одна живая собственная модель с текущим OC >0 в 3 Engine после Final Pulse. Текущая потеря tag не стирает уже выполненную работу. Если кандидат один, он выигрывает. Если оба - выигрывает имеющий больше VP. Если оба равны по VP либо кандидатов нет - **общее поражение**.\n\nНельзя выиграть одними VP без работы с машиной, но одиночный последний перехват tag больше не отменяет четыре раунда накопленного контроля. Соперника можно лишить подхода, физического OC, условий OVERRIDE или последних моделей у Engine. Условия одинаковы для обеих фракций.\n\nПобедитель выбирает PURGE/SEIZE/FEED либо SEAL при 3 Fragments. Home не захватывается; это победа через контроль машины. Терминальный aftermath: XP, Casualty и эпилог; без дохода, D66 и новых ходов. При общем поражении живых не объявляют погибшими автоматически: каждый выбирает выживший ID для сцены эвакуации.","PACT":"Каждая сторона берёт до **50% AL** из своего Field Roster: обычно 1000 +1000. Собственные Unit Limits этого формата, до двух Enhancements, ровно один legal detachment из Stage Package независимо от DP. Нет Recon Lock, Interdict или Underdog. Тайный одновременный commitment. CP, армейские способности, repairs, auras и Stratagems действуют только на собственную половину; союзники friendly для движения/Engagement, но не входят в «вашу армию» для buffs. Cross-faction Attachments запрещены.\n\nПоле 60×44. Deathwatch y≤12, Necrons y≥32. Engine (30,22). **Seals: (18,22), (42,22), (30,22)**; центральный Seal совпадает с Engine по footprint, interactions разные. Это исправляет прежнюю разницу расстояний между сторонами. Seals - interaction objects, не objectives. Расставить terrain симметрично, обеспечить проходы и хотя бы одну линию стрельбы к каждому Seal с обеих половин. Обычный roll-off первого игрока; по одному ходу каждого за раунд, затем короткая Echo phase машины.\n\n## Ключи и канал\n\nУ каждого Seal два поля: Biometrics и Engram. Deathwatch делает **ENCODE BIOMETRICS**, Necrons **ENCODE ENGRAM**: обычный Action в 3. Начать можно при живом Echo, но к completion оно должно быть уничтожено: другой отряд может расчистить узел стрельбой/боем в том же ходу. Это специальное условие проверяется только при completion, иначе восстановление Echo в начале раунда блокировало бы первого игрока. Максимум **один начатый ENCODE на сторону за собственный ход**, включая неудачный. Заполненное своё поле повторно не записывается. Два ключа стабилизируют Seal навсегда и снижают Instability на 2, минимум 0. Записанные ключи не стираются при гибели actor или возвращении Echo.\n\nС R4 после стабилизации всех трёх Seals **PRIME ENGINE**: CORE Action в 3 Engine; формация не Shoot/Charge, без ускорений. Completion назначает её Channeler стороны. Prime гаснет при любом move (включая реакцию), уходе с поля/из range, уничтожении или Battle-shock. Очищение Battle-shock не восстанавливает Prime; нужно повторить Action. Максимум один активный Channeler каждой стороны. Можно переделать на другую формацию, прежний Prime исчезает при новом completion.\n\n## Instability\n\nНачинается с 0. В начале каждого R +2. При 12 немедленное общее поражение; ниже применить Pulse (R1 только предупреждение). В конце R1-R4, если есть нестабилизированный Seal и за весь раунд не записан ни один ключ, ещё +1 и немедленная проверка 12. Закрытие всех Seals отменяет только эту добавку за бездействие.\n\n| Instability | Pulse в начале R2-R5 |\n| --- | --- |\n| 0-3 | Формации в 3 любого нестабилизированного Seal тестируют Battle-shock. |\n| 4-5 | Каждая сторона выбирает одну свою формацию в 6 нестабилизированного Seal: 1 mortal wound. |\n| 6-7 | То же, но D3 mortal wounds. |\n| 8-11 | Каждая сторона выбирает две разные свои формации в 6 нестабилизированного Seal или Engine: каждой D3 mortal wounds. |\n\nЕсли eligible меньше требуемого, выбрать всех; если 0, эффекта нет. Overlap не даёт повторного Pulse. **SUPPRESS ECHO:** раз на сторону за раунд формация, eligible to shoot и не выполняющая Action, вместо всей своей стрельбы, в 18 и видимости Engine: D6 3+ снизить Instability на 1 либо заглушить одну живую видимую Echo в 18 до конца текущей Echo phase. Выбор до roll. Это не Named Action/OPERATE и само не запрещает Charge. Обычные атаки по Echo вместо Suppress разрешены.\n\nМашина создаёт три неподвижных боевых эха, по одному на каждом Seal. Используйте любые согласованные модели или жетоны на **40-мм круглой базе**; высота для видимости условно 3. Они не требуют третьей коллекции и не являются настоящими подразделениями кампании. До deployment стоят по центрам Seals; центральная Echo также закрывает доступ к Engine.\n\n| Echo Construct | Профиль |\n| --- | --- |\n| Характеристики | M 0; T 7; Sv 3+; W 10; Ld 7+; OC 0. Одна модель, VEHICLE; без faction keyword, Invulnerable save и других abilities. |\n| Echo Lance | Range 18; A 8; BS 4+; S 6; AP -1; D 2. |\n| Memory Blades | Melee; A 4; WS 4+; S 6; AP -1; D 2. |\n\nЭто enemy обеим сторонам для targeting, Charge, Engagement, defensive abilities и обычных weapon rules. Не XENOS и не NECRONS; anti-VEHICLE действует. Не блокирует видимость другим моделям как terrain. Не двигается, не Advance/Charge, не проходит Battle-shock, не выполняет Actions, не получает CP и не имеет фазы Command. Гибель не даёт HUNT, bounty, дополнительных Supply или persistent XP; боевые kill-trigger способности работают по обычным правилам. Уничтоженная Echo убирается, остаётся Seal marker.\n\n**Распорядок.** R1: Echo уже стоят, игроки могут их атаковать; машина в конце R1 не атакует. Начало R2-R5: Instability/Pulse, затем восстановить каждую уничтоженную Echo у нестабилизированного Seal с полными wounds. Живая повреждённая Echo wounds не восстанавливает. У стабилизированного Seal Echo не возвращается. Если место занято, поставить как можно ближе к центру в пределах 3, вне Engagement; при равных местах выбрать совместно до любых бросков. Нет legal места - эту Echo не восстановить в этом раунде. Нельзя поставить поверх модели.\n\n**Echo phase в конце R2-R5:** после завершения обоих ходов каждое живое незаглушённое Echo один раз атакует; порядок Seal слева направо по x, при равном x меньший y. Если engaged - Memory Blades в ближайшую engaged формацию; иначе Echo Lance в ближайшую видимую формуцию в 18. Нет подходящей цели - пропустить. Это отдельное разрешение одного профиля по обычным hit/wound/save/damage, без pile-in/consolidation, Stratagems машины или дополнительного ответного Fight. Игроки могут применять defensive rules с подходящим trigger. Echo не активируется в обычные Fight phases; атаковать её своими eligible units в них можно.\n\nРасстояние цели считается от ближайших баз. При равенстве - цель стороны, ходившей первой в нечётном раунде и второй в чётном; затем меньший persistent ID. При выборе между Attached компонентами используется ID bearer/Warlord, иначе минимальный ID формации. Модели и цели не меняются после бросков. Стрельба/бой Echo остаются обычными боевыми бросками за столом; приложение только подсказывает профиль и порядок.\n\n**Финальная проверка:** в конце R5 после Echo phase Final Pulse даёт каждой формации в 3 Engine 1 mortal wound. Если все три Seals стабилизированы и оба Channeler живы, не Battle-shocked, в range и с действующим Prime -> **CONCORDAT, победа обоих**. Иначе общее поражение. VP нет; приложение показывает 0-6 ключей и 0-2 Primes. Channeler может быть любой legal формацией с OC >0, не только CHARACTER.\n\nОба сохраняют Home и самостоятельность; перемирие остановило конкретную катастрофу. Каждый выбирает участвовавший ID как Keeper of the Pact, только сюжетный титул. Погибшие делают обычный Casualty, живым не добавляется Damage. Никаких дополнительных Echo Burst из старой 2.2: их заменили эти проекции. Income/D66/Logistics после финала нет."}
export const EQUIPMENT_EFFECTS:Record<string,string> = {"Medicae / Repair Node":"Consumable. После полного Casualty package предотвратить 1 новый Damage, не опуская ниже прежнего Damage. Не отменяет Scar/Critical/Lost. Без предотвращённого Damage не расходуется.","Reinforced Plating":"Одна атака по bearer model: Damage -1, минимум 1.","Tactical Relay":"Один обычный Action начинает bearer в 6 вместо 3. Должен остаться в этом range до completion. Не CORE/CLAIM/DELIVER/FEED; не меняет OC и reward rolls.","Reserve Beacon":"Один Charge reroll в ход прибытия формации из резервов/Pool.","Recovery Cache":"Consumable: оплатить до 30 стоимости одного законного Damage recovery step. Остаток сгорает; не Rehab, debt или Commission. Не обходит Window.","Blackglass Ward":"Один Battle-shock reroll любого происхождения.","Combat Auspex":"Одна Shooting activation bearer игнорирует Cover.","Blackglass Shard":"Reroll Battle-shock.","Chronal Sliver":"Reroll Advance или Charge.","Ossuary Key":"+1 VP за обычный завершённый Action, в пределах cap; не CORE/CLAIM.","Blackglass Lens":"Один ranged profile игнорирует Cover в одной activation.","Mnemonic Crown":"После Action +2 total OC до следующей своей Command.","Anchor Fragment":"После enemy Normal Move в 9: Normal Move до 3, заканчивая дальше 6 от enemy."}
